def image(asset, x, y, width, height):
    return (f'<image href="{ASSETS[asset]}" x="{x}" y="{y}" width="{width}" '
            f'height="{height}" preserveAspectRatio="none"/>')


def rect(x, y, w, h, fill, radius=0, stroke="none", sw=1, extra=""):
    return (f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{radius}" '
            f'fill="{fill}" stroke="{stroke}" stroke-width="{sw}" {extra}/>')


def label(x, y, value, size=14, color="#fff", weight=750, anchor="middle", extra=""):
    return (f'<text x="{x}" y="{y}" font-family="DejaVu Sans,Arial,sans-serif" font-size="{size}" '
            f'font-weight="{weight}" fill="{color}" text-anchor="{anchor}" {extra}>{escape(value)}</text>')


def button(key, title, drawing):
    return (f'<g class="action" tabindex="0" role="button" data-action="{key}" '
            f'aria-label="{escape(title, quote=True)}"><title>{escape(title)}</title>{drawing}</g>')


def die(x, y, color="#ffa400"):
    return (rect(x, y, 66, 66, color, 10, "#fff", 5)
            + f'<circle cx="{x+33}" cy="{y+33}" r="6" fill="#fff"/>')


