COLORS = dict(Red="#f03549",Orange="#ffa400",Yellow="#f5cc16",Green="#289655",Blue="#416cf3",Purple="#ab4ed0")
BADGE = ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 84 28" width="84" height="28">'
         +rect(1,1,82,26,"#18181c",7,"#77777e")+label(42,18,"Next roll ▾",11)+'</svg>')
HEAD = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Offline Dice</title><style>
*{box-sizing:border-box}html{color-scheme:dark;background:#000}body{margin:0;background:#000;color:#fff;font:600 14px system-ui, sans-serif;padding-bottom:clamp(42px,5vw,86px)}#scene{display:block;width:100%;max-width:1536px;margin:auto;height:auto}button,select{font:inherit;color:inherit;cursor:pointer}button:focus-visible,select:focus-visible,summary:focus-visible,.action:focus-visible{outline:3px solid #ffc358;outline-offset:2px}.action{cursor:pointer}.action:hover{filter:brightness(1.12)}.corner{position:fixed;z-index:3;top:max(8px,env(safe-area-inset-top));right:8px}.corner summary{list-style:none;cursor:pointer;float:right}.corner summary::-webkit-details-marker{display:none}.corner label{display:block;clear:both;padding:11px;background:#19191e;border:1px solid #666;border-radius:8px}.corner select{display:block;width:100%;margin-top:6px;padding:5px}.foot{position:fixed;inset:auto 0 0;width:100%;max-height:62px;display:block}.overlay{position:fixed;inset:0;z-index:4;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:auto;background:#000 var(--roll-bg) center center/cover no-repeat}.overlay h2{font:1000 clamp(30px,3.3vw,52px) system-ui;text-shadow:1px 3px 1px #595959;margin:0 0 24px}.animated{display:flex;justify-content:center;flex-wrap:wrap;max-width:88vw;max-height:65vh;gap:8px;overflow:auto}.animated i{width:clamp(40px,6vw,94px);aspect-ratio:1;border:6px solid white;border-radius:16%;background:radial-gradient(circle,white 0 12%,#dedede 13%);animation:tumble .5s alternate ease-in-out infinite}.animated.wheel i{border-radius:50%;background:conic-gradient(red,orange,yellow,green,blue,purple,red)}@keyframes tumble{to{transform:rotate(87deg) scale(.85)}}[hidden]{display:none!important}dialog{color:white;width:min(290px,92vw);max-height:70vh;background:#222228;border:1px solid #777;border-radius:14px;padding:17px;box-shadow:0 12px 45px #000a}dialog::backdrop{background:#0008}dialog h2{font-size:17px;margin:0 0 12px}.choices{display:grid;gap:6px}.choices button,dialog form button{background:#343439;border:1px solid #555;border-radius:7px;text-align:left;padding:8px}.choices img{vertical-align:middle}.choices button[aria-pressed=true]{border-color:#ffa400}dialog form button{margin-top:12px}#record{line-height:1.5;overflow-wrap:anywhere}.sr{position:absolute;width:1px;height:1px;clip-path:inset(50%);overflow:hidden}@media(max-width:650px){.foot{height:22px;object-fit:cover;object-position:center}.corner{top:4px;right:4px}}@media(prefers-reduced-motion:reduce){.animated i{animation:none}}</style></head><body>"""
JS = r"""
const $ = id => document.getElementById(id);
const names = Object.keys(colors);
const svgNS = 'http://www.w3.org/2000/svg';
const state = {count:4, mode:'COLOR DICE', theme:'BLACK', score:0, busy:false, last:null, history:[], extra:0};
const visitor = Array.from(crypto.getRandomValues(new Uint32Array(2))).join('-');
function randomIndex(n) {
  const sample = new Uint32Array(1);
  const cap = 2**32 - (2**32 % n);
  do { crypto.getRandomValues(sample); } while (sample[0] >= cap);
  return sample[0] % n;
}
function node(tag, attrs) {
  const element = document.createElementNS(svgNS,tag);
  for (const [name,value] of Object.entries(attrs)) element.setAttribute(name,value);
  return element;
}
function resize() {
  const mobile = matchMedia('(max-width:650px)').matches;
  $('scene').setAttribute('viewBox',(mobile?'337 0 435 ':'0 0 1111 ')+(1190+state.extra));
}
resize();window.addEventListener('resize',resize);
function result(values,wheel) {
  const group = $('dice'); group.replaceChildren();
  const cols = Math.min(5,values.length);
  state.extra = (Math.ceil(values.length/cols)-1)*76;
  values.forEach((name,i)=>{
    const row = Math.floor(i/cols), inRow = Math.min(cols,values.length-row*cols);
    const x=555-(inRow*76-10)/2+(i%cols)*76, y=286+row*76;
    const g=node('g',{'aria-label':name});
    const title=node('title',{});title.textContent=name;g.append(title);
    if(wheel) {
      names.forEach((c,j)=>{
        const a=(j-1.5)*Math.PI/3,b=a+Math.PI/3,cx=x+33,cy=y+33;
        g.append(node('path',{d:'M '+cx+' '+cy+' L '+(cx+32*Math.cos(a))+' '+(cy+32*Math.sin(a))+' A 32 32 0 0 1 '+(cx+32*Math.cos(b))+' '+(cy+32*Math.sin(b))+' Z',fill:colors[c]}));
      });
      g.append(node('circle',{cx:x+33,cy:y+33,r:17,fill:colors[name],stroke:'white','stroke-width':3}));
    } else {
      g.append(node('rect',{x,y,width:66,height:66,rx:10,fill:colors[name],stroke:'white','stroke-width':5}),
               node('circle',{cx:x+33,cy:y+33,r:6,fill:'white'}));
    }
    group.append(g);
  });
  group.setAttribute('aria-label',values.join(', '));$('below').setAttribute('transform','translate(0 '+state.extra+')');
  $('board').setAttribute('height',1030+state.extra);resize();
}
function today(increment=0) {
  const key='offline-dice:'+new Date().toLocaleDateString('en-CA');
  try { const n=Number(localStorage.getItem(key)||0)+increment;localStorage.setItem(key,n);$('today').textContent='Rolls Today: '+n; } catch {}
}
async function stats(n=0) {
  try {
    const r=await fetch('/stats',{method:'POST',body:JSON.stringify({visitor,n})});
    if(!r.ok)return;
    const data=await r.json(),progress=Math.min(1,data.total/250000);
    $('online').textContent='Users Online: '+data.online;$('percent').textContent=Math.floor(progress*100)+'%';
    $('bar').setAttribute('width',360*progress);$('total').textContent='Total World Rolls: '+data.total.toLocaleString()+' / 250,000';
  } catch {}
}
async function roll() {
  if(state.busy)return;state.busy=true;
  const excluded=$('exclude').value, pool=names.filter(name=>name!==excluded);
  const values=Array.from({length:state.count},()=>pool[randomIndex(pool.length)]);
  const wheel=state.mode==='WHEEL';
  $('exclude').value='';$('corner').open=false;
  $('animation').replaceChildren(...values.map(()=>document.createElement('i')));
  $('animation').classList.toggle('wheel',wheel);$('overlay').hidden=false;
  try {
    await new Promise(resolve=>setTimeout(resolve,1250));result(values,wheel);
    const id=Array.from({length:10},()=>'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'[randomIndex(36)]).join('');
    state.last={id,excluded,values};state.history.unshift(values);state.history.splice(25);
    $('roll-id').textContent='ID: '+id;$('announce').textContent=values.join(', ');
    $('history').replaceChildren(...state.history.map((values,i)=>{
      const square=node('rect',{x:369+i*15,y:800,width:11,height:11,rx:2,fill:colors[values[0]]});
      const title=node('title',{});title.textContent=values.join(', ');square.append(title);return square;
    }));
    today(1);stats(values.length);
  } finally { $('overlay').hidden=true;state.busy=false; }
}
function openMenu(title,choices,current,onPick) {
  $('dialog-title').textContent=title;$('record').textContent='';$('choices').replaceChildren();
  for(const value of choices) {
    const btn=document.createElement('button');btn.type='button';btn.textContent=String(value);
    btn.setAttribute('aria-pressed',value===current);
    if(title==='Score item') {const img=new Image(38,35);img.src=items[value-1];img.alt='';btn.prepend(img);}
    btn.onclick=()=>{onPick(value);$('menu').close()};$('choices').append(btn);
  }
  $('menu').showModal();
}
let item=1,blurred=false;
function activate(key) {
  if(state.busy)return;
  if(key==='roll')return roll();
  if(key.startsWith('score')){state.score+=Number(key.slice(5));$('score').textContent=(state.score>=0?'+':'')+state.score;return}
  if(key==='blur'){blurred=!blurred;$('rails').style.filter=blurred?'blur(3px)':'';$('blur-label').textContent=blurred?'BLUR ON':'';$('blur-label').style.paintOrder='stroke';$('blur-label').setAttribute('stroke',blurred?'#19191c':'none');$('blur-label').setAttribute('stroke-width',6);return}
  if(key==='verify'){openMenu('Last roll',[],null,()=>{});const last=state.last;$('record').textContent=last?'ID '+last.id+' · Excluded: '+(last.excluded||'None')+' · '+last.values.join(', '):'Roll the dice to view a result.';return}
  if(key==='items')return openMenu('Score item',[1,2,3,4],item,value=>{item=value;$('chosen-item').setAttribute('href',items[item-1])});
  const settings={count:['Number of dice',Array.from({length:100},(_,i)=>i+1)],mode:['Roll mode',['COLOR DICE','WHEEL']],theme:['Board color',['BLACK','WHITE']]};
  const [title,choices]=settings[key];
  openMenu(title,choices,state[key],value=>{state[key]=value;$(key+'-label').textContent=key==='count'?value+' DICE':value;
    if(key==='theme'){$('board').setAttribute('fill',value==='BLACK'?'#101012':'#646468')}});
}
document.querySelectorAll('[data-action]').forEach(g=>{
  g.addEventListener('click',()=>activate(g.dataset.action));
  g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate(g.dataset.action)}});
});
today();stats();setInterval(()=>stats(),30000);
"""
BODY = (HEAD + scene() + '<details class="corner" id="corner"><summary aria-label="Next roll settings">'+BADGE+'</summary>'
        '<label>Exclude next color<select id="exclude"><option value="">None</option>'
        +''.join('<option>'+name+'</option>' for name in COLORS)+'</select></label></details>'
        +'<img class="foot" alt="VIP Login · English · Our TikTok · Our Discord · Updates" src="'+ASSETS["footer"]+'">'
        +'<div class="overlay" id="overlay" hidden style="--roll-bg:url('+ASSETS["rollWorld"]+')"><h2>LET’S SEE…</h2><div class="animated" id="animation"></div></div>'
        +'<dialog id="menu" aria-labelledby="dialog-title"><h2 id="dialog-title"></h2><div class="choices" id="choices"></div>'
        +'<p id="record"></p><form method="dialog"><button>Close</button></form></dialog><span class="sr" id="announce" aria-live="polite"></span>'
        +'<script>const colors='+json.dumps(COLORS)+';const items='+json.dumps([ASSETS['item'+str(i)] for i in range(4)])+';'
        +JS+'</script></body></html>').encode()

visitors = {}
world_total = 0
stats_lock = threading.Lock()


class Site(BaseHTTPRequestHandler):
    def reply(self, status, mime, body):
        self.send_response(status)
        self.send_header("Content-Type", mime)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def do_GET(self):
        path = self.path.partition("?")[0]
        if path == "/health":
            self.reply(200, "text/plain", b"ok")
        elif path in ("/", "/index.html"):
            self.reply(200, "text/html; charset=utf-8", BODY)
        else:
            self.send_error(404)

    do_HEAD = do_GET

    def do_POST(self):
        global world_total
        if self.path != "/stats":
            return self.send_error(404)
        try:
            length = int(self.headers.get("Content-Length", 0))
            if not 0 < length <= 256:
                raise ValueError()
            data = json.loads(self.rfile.read(length))
            visitor, count = data["visitor"], data["n"]
            if not isinstance(visitor, str) or not 1 <= len(visitor) <= 64 or type(count) != int or not 0 <= count <= 100:
                raise ValueError()
        except (ValueError, KeyError, TypeError):
            return self.send_error(400)
        now = time.monotonic()
        with stats_lock:
            for key in [k for k,t in visitors.items() if now-t > 90]:
                del visitors[key]
            visitors[visitor] = now
            world_total += count
            response = json.dumps({"online":len(visitors),"total":world_total}).encode()
        self.reply(200, "application/json", response)


if __name__ == "__main__":
    port = int(os.environ.get("PORT","10000"))
    print(f"Offline Dice listening on port {port}", flush=True)
    ThreadingHTTPServer(("0.0.0.0",port), Site).serve_forever()
